import{_ as t,a,c as o,ac as n}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第三册：培养技能 · Lesson 48 The silent village","description":"学习 地点前置的完全倒装，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第三册：培养技能 · Lesson 48 The silent village","description":"学习 地点前置的完全倒装，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第3册课时","summary":"学习 地点前置的完全倒装，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第三册：培养技能 · Lesson 47 Too high a price?","link":"/life/english/new-concept/book-3/unit-03/lesson-047"},"next":{"text":"第三册：培养技能 · Lesson 49 The ideal servant","link":"/life/english/new-concept/book-3/unit-03/lesson-049"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第三册：培养技能 · Lesson 47 Too high a price?","link":"/life/english/new-concept/book-3/unit-03/lesson-047"},"next":{"text":"第三册：培养技能 · Lesson 49 The ideal servant","link":"/life/english/new-concept/book-3/unit-03/lesson-049"}},"headers":[],"relativePath":"life/english/new-concept/book-3/unit-03/lesson-048.md","filePath":"life/english/new-concept/book-3/unit-03/lesson-048.md"}'),i={name:"life/english/new-concept/book-3/unit-03/lesson-048.md"};function s(l,e,r,d,h,c){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="第三册-培养技能-·-lesson-48-the-silent-village" tabindex="-1">第三册：培养技能 · Lesson 48 The silent village <a class="header-anchor" href="#第三册-培养技能-·-lesson-48-the-silent-village" aria-label="Permalink to &quot;第三册：培养技能 · Lesson 48 The silent village&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-3/contents">本册目录</a> · <a href="/life/english/new-concept/book-3/unit-03/overview">单元 3</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>从安静村落或被遗弃地点的观察练习克制的场景描写。寂静可能来自时间、季节或人口变化，不能只凭景象编造唯一原因。学习地点状语前置的完全倒装，用空间顺序引入新对象，同时知道代词主语通常不照搬这一倒装形式。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>deserted</td><td>/dɪˈzɜːtɪd/</td><td>adj.</td><td>荒无人烟的</td><td>a deserted street</td></tr><tr><td>courtyard</td><td>/ˈkɔːtjɑːd/</td><td>n.</td><td>庭院</td><td>an empty courtyard</td></tr><tr><td>shutter</td><td>/ˈʃʌtə/</td><td>n.</td><td>百叶窗</td><td>closed shutters</td></tr><tr><td>silence</td><td>/ˈsaɪləns/</td><td>n.</td><td>寂静</td><td>complete silence</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>in the distance — 在远处</li><li>give the impression of — 给人某种印象，未必等于事实</li></ul><h2 id="语法讲解-地点前置的完全倒装" tabindex="-1">语法讲解：地点前置的完全倒装 <a class="header-anchor" href="#语法讲解-地点前置的完全倒装" aria-label="Permalink to &quot;语法讲解：地点前置的完全倒装&quot;">​</a></h2><p>地点副词或介词短语置前，有时可使用地点加谓语加名词主语的完全倒装，例如 At the end of the road stood a tower，常用于描写场景和引入新信息。谓语一般是不及物的存在、位置或移动动词，不能把任意及物句都这样倒装。若主语是人称代词，通常保持正常语序，如 Here it comes，而不是 Here comes it。主谓一致仍由后置主语决定；这种形式较文学化，连续滥用会让叙述不自然。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>Beyond the empty square stood a row of houses with closed shutters.</p></blockquote><p>空旷广场的另一边立着一排百叶窗紧闭的房屋。</p><p>地点短语前置，stood 在名词主语 a row of houses 之前，构成完全倒装。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>Here comes it 应为 Here it comes；代词主语通常不按名词主语的方式后置。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>读地点短语时保持未结束的语调，再清楚读出 stood 和后置主语；尝试只听录音画出巷口与候车亭的位置。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>At the end of the lane stood an empty bus shelter. No voices came from the nearby houses. We could not tell whether the residents were away or simply indoors.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>用三句描绘一处安静场景，包含一个倒装句并避免臆断。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>倒装建立空间，最后一句主动限制对静默的解释。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>还原例句为普通语序。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> A row of houses with closed shutters stood beyond the empty square.</p><p><strong>解析：</strong> 把主语移回谓语前，地点置后。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>选择：Here ___.（it comes/comes it）</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> it comes</p><p><strong>解析：</strong> 人称代词主语通常不倒装。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>关闭窗户能否证明村里无人居住？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 不能。</p><p><strong>解析：</strong> 这是观察线索，尚不足以排除其他原因。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：地点前置的完全倒装。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-3/unit-03/grammar">单元语法</a> · <a href="/life/english/new-concept/book-3/unit-03/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-3/unit-03/review">单元自测</a></p><p><a href="/life/english/new-concept/book-3/unit-03/lesson-047">上一课</a> · <a href="/life/english/new-concept/book-3/unit-03/overview">单元目录</a> · <a href="/life/english/new-concept/book-3/unit-03/lesson-049">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const b=t(i,[["render",s]]);export{u as __pageData,b as default};
